  for (const ev of events) processEvent(store, POLICY, ev);
  const before = snapshot(dir);
  store = new Store(dir);
  for (const ev of events) assert.equal(processEvent(store, POLICY, ev).outcome, "duplicate");
  assert.deepEqual(snapshot(dir), before);
  assert.equal(store.listRefunds().length, 1);
  assert.equal(store.listRefunds()[0].status, "cancelled");
