test("cancelling auto-approved refunds is audited only once", (t) => {
  const dir = mkdtempSync(join(tmpdir(), "pay381-cancel-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const store = new Store(dir);
  processEvent(store, POLICY, event("evt_approved"));
  const cancel = event("evt_ignored_cancel", "refund.cancelled");
  assert.equal(processEvent(store, POLICY, cancel).outcome, "ignored");
  const before = snapshot(dir);
  assert.equal(processEvent(store, POLICY, cancel).outcome, "duplicate");
  assert.deepEqual(snapshot(dir), before);
  assert.equal(store.listRefunds()[0].status, "auto_approved");
  assert.equal(readFileSync(join(dir, "audit.jsonl"), "utf8").trim().split("\n").length, 2);
});

test("configured INR auto-approval boundary is inclusive at 500000 minor units", () => {
