    { status: 200, body: { received: true, duplicate: true } });
  assert.deepEqual(snapshot(dir), before);
  assert.equal(store.loadRawEvent("evt_http"), body);
  assert.equal((await post(body)).status, 401);
  assert.deepEqual(snapshot(dir), before);
  const ignored = JSON.stringify({ event_id: "evt_other", type: "payment.updated", created: NOW, data: {} });
  assert.deepEqual(await post(ignored, { "paygate-signature": signature(ignored, now) }),
    { status: 200, body: { received: true, duplicate: false } });
  const ignoredBefore = snapshot(dir);
  assert.equal((await post(ignored, { "paygate-signature": signature(ignored, now) })).body.duplicate, true);
  assert.deepEqual(snapshot(dir), ignoredBefore);
  assert.equal((await fetch(`${base}/admin/refunds`)).status, 401);
  assert.equal((await fetch(`${base}/admin/replay/evt_http`, { method: "POST", headers: { authorization: "Bearer viewer-key" } })).status, 403);
